## 3-9. DataSourceAdapter 인터페이스 설계

### 1. DataSourceAdapter 인터페이스 정의

```kotlin
// datasource/adapter/DataSourceAdapter.kt
interface DataSourceAdapter : AutoCloseable {

    /** 데이터 소스 연결 초기화 */
    fun connect(config: DataSourceInfo)

    /** 연결 테스트 (connect 없이 독립 실행 가능) */
    fun testConnection(config: DataSourceInfo): TestConnectionResult

    /**
     * 배치 단위 데이터 조회.
     * @param query SQL 또는 소스별 쿼리 문자열
     * @param batchSize 한 번에 가져올 행 수
     * @param cursor 이전 배치의 커서 (최초 호출 시 null)
     * @return DataBatch (rows + nextCursor)
     */
    fun fetchBatch(query: String, batchSize: Int, cursor: Any? = null): DataBatch

    /** 전체 행 수 추정 (프로그레스 표시용, 정확하지 않을 수 있음) */
    fun estimateTotal(query: String): Long
}

data class DataBatch(
    val rows: List<Map<String, Any?>>,
    val nextCursor: Any?,         // null이면 마지막 배치
    val fetchedCount: Int,
)

data class TestConnectionResult(
    val success: Boolean,
    val message: String,
    val metadata: Map<String, Any> = emptyMap(),  // DB 버전, 테이블 목록 등
)
```

### 2. JdbcDataSourceAdapter 구현 방안

```kotlin
// datasource/adapter/JdbcDataSourceAdapter.kt
@Component
class JdbcDataSourceAdapter : DataSourceAdapter {
    private var connection: java.sql.Connection? = null

    override fun connect(config: DataSourceInfo) {
        require(config.type == DataSourceType.JDBC || config.type == DataSourceType.HIVE)
        Class.forName(config.driver)
        connection = DriverManager.getConnection(
            config.url, config.username, config.password
        )
    }

    override fun testConnection(config: DataSourceInfo): TestConnectionResult =
        runCatching {
            Class.forName(config.driver)
            DriverManager.getConnection(config.url, config.username, config.password).use { conn ->
                val meta = conn.metaData
                TestConnectionResult(
                    success = true,
                    message = "연결 성공",
                    metadata = mapOf(
                        "dbProductName" to meta.databaseProductName,
                        "dbVersion" to meta.databaseProductVersion,
                    )
                )
            }
        }.getOrElse { e ->
            TestConnectionResult(false, e.message ?: "연결 실패")
        }

    override fun fetchBatch(query: String, batchSize: Int, cursor: Any?): DataBatch {
        val conn = connection ?: throw IllegalStateException("connect() 호출 필요")
        val offset = (cursor as? Long) ?: 0L
        // LIMIT/OFFSET 기반 페이징 (DB 종류별 분기 가능)
        val pagedQuery = "$query LIMIT $batchSize OFFSET $offset"
        val stmt = conn.createStatement()
        val rs = stmt.executeQuery(pagedQuery)
        val meta = rs.metaData
        val rows = mutableListOf<Map<String, Any?>>()
        while (rs.next()) {
            val row = mutableMapOf<String, Any?>()
            for (i in 1..meta.columnCount) {
                row[meta.getColumnLabel(i)] = rs.getObject(i)
            }
            rows.add(row)
        }
        rs.close(); stmt.close()
        val nextCursor = if (rows.size < batchSize) null else offset + batchSize
        return DataBatch(rows, nextCursor, rows.size)
    }

    override fun estimateTotal(query: String): Long {
        val conn = connection ?: return 0L
        return runCatching {
            val countQuery = "SELECT COUNT(*) FROM ($query) AS t"
            conn.createStatement().use { stmt ->
                stmt.executeQuery(countQuery).use { rs ->
                    if (rs.next()) rs.getLong(1) else 0L
                }
            }
        }.getOrDefault(0L)
    }

    override fun close() {
        connection?.close()
        connection = null
    }
}
```

**핵심 설계 포인트**: `JdbcDataSourceAdapter`는 `@Component`이지만 **Prototype scope** 또는 **팩토리 패턴**으로 사용해야 합니다. 색인 작업마다 별도 인스턴스가 필요합니다 (Connection 상태 보유):

```kotlin
// datasource/adapter/DataSourceAdapterFactory.kt
@Component
class DataSourceAdapterFactory {
    fun create(type: DataSourceType): DataSourceAdapter = when (type) {
        DataSourceType.JDBC, DataSourceType.HIVE -> JdbcDataSourceAdapter()
        // Phase 4:
        // DataSourceType.MONGODB -> MongoDataSourceAdapter()
        // DataSourceType.KAFKA -> KafkaDataSourceAdapter()
        else -> throw UnsupportedOperationException("미지원 데이터 소스: $type")
    }
}
```

### 3. Hue/Hive/Impala 확장

JDBC 재사용이므로 **드라이버만 추가**합니다:

