## 3-10. 집계 쿼리 빌더 Tier 1 설계

### 1. Tier 1 지원 집계 유형 (8개)

MIGRATION_ROADMAP.md 섹션 8.2 확정 기준:

| 카테고리 | 집계 | ES 9.x Java API Client 메서드 | 필요 필드 타입 |
|---------|------|-------------------------------|--------------|
| Bucket | `terms` | `Aggregation.of(a -> a.terms(t -> t.field(f).size(s)))` | keyword, ip |
| Bucket | `date_histogram` | `Aggregation.of(a -> a.dateHistogram(d -> d.field(f).calendarInterval(i)))` | date |
| Bucket | `histogram` | `Aggregation.of(a -> a.histogram(h -> h.field(f).interval(i)))` | integer, long, float, double |
| Bucket | `range` | `Aggregation.of(a -> a.range(r -> r.field(f).ranges(List)))` | integer, long, float, double |
| Bucket | `filter/filters` | `Aggregation.of(a -> a.filters(f -> f.filters(buckets)))` | any (쿼리 기반) |
| Metric | `avg/sum/min/max` | `Aggregation.of(a -> a.avg(m -> m.field(f)))` | integer, long, float, double |
| Metric | `cardinality` | `Aggregation.of(a -> a.cardinality(c -> c.field(f)))` | any |
| Metric | `value_count` | `Aggregation.of(a -> a.valueCount(v -> v.field(f)))` | any |

### 2. AggregationDslBuilder 구현 전략

```kotlin
// aggregation/service/AggregationDslBuilder.kt
@Component
class AggregationDslBuilder {

    /**
     * AggregationNode 트리 → ES Java API Client의 Map<String, Aggregation> 변환.
     * 재귀적으로 sub-aggregation을 처리한다.
     */
    fun build(nodes: List<AggregationNode>): Map<String, Aggregation> {
        return nodes.associate { node ->
            node.name to buildSingle(node)
        }
    }

    private fun buildSingle(node: AggregationNode): Aggregation {
        val subAggs = if (node.subAggregations.isNotEmpty()) {
            build(node.subAggregations)  // 재귀
        } else emptyMap()

        return Aggregation.of { agg ->
            // sub-aggregation 연결
            if (subAggs.isNotEmpty()) agg.aggregations(subAggs)

            when (node.type) {
                AggregationType.TERMS -> agg.terms { t ->
                    t.field(node.field)
                    node.params["size"]?.let { t.size(it.toString().toInt()) }
                    t
                }
                AggregationType.DATE_HISTOGRAM -> agg.dateHistogram { d ->
                    d.field(node.field)
                    val interval = node.params["calendar_interval"]?.toString() ?: "day"
                    d.calendarInterval(CalendarInterval.valueOf(interval.uppercase()))
                    node.params["format"]?.let { d.format(it.toString()) }
                    d
                }
                AggregationType.HISTOGRAM -> agg.histogram { h ->
                    h.field(node.field)
                    h.interval(node.params["interval"]?.toString()?.toDouble() ?: 10.0)
                    h
                }
                AggregationType.RANGE -> agg.range { r ->
                    r.field(node.field)
                    val ranges = node.params["ranges"] as? List<Map<String, Any?>> ?: emptyList()
                    ranges.forEach { range ->
                        r.ranges { rb ->
                            range["from"]?.let { rb.from(it.toString()) }
                            range["to"]?.let { rb.to(it.toString()) }
                            range["key"]?.let { rb.key(it.toString()) }
                            rb
                        }
                    }
                    r
                }
                AggregationType.FILTERS -> agg.filters { f ->
                    // keyed filters
                    val buckets = node.params["filters"] as? Map<String, Any> ?: emptyMap()
                    f.filters { fb ->
                        fb.keyed(
                            buckets.mapValues { (_, v) ->
                                Query.of { q -> q.queryString { qs -> qs.query(v.toString()) } }
                            }
                        )
                    }
                    f
                }
                AggregationType.AVG -> agg.avg { it.field(node.field) }
                AggregationType.SUM -> agg.sum { it.field(node.field) }
                AggregationType.MIN -> agg.min { it.field(node.field) }
                AggregationType.MAX -> agg.max { it.field(node.field) }
                AggregationType.COUNT -> agg.valueCount { it.field(node.field) }
                AggregationType.CARDINALITY -> agg.cardinality { it.field(node.field) }
                AggregationType.VALUE_COUNT -> agg.valueCount { it.field(node.field) }
            }
        }
    }
}

enum class AggregationType {
    TERMS, DATE_HISTOGRAM, HISTOGRAM, RANGE, FILTERS,
    AVG, SUM, MIN, MAX, COUNT, CARDINALITY, VALUE_COUNT,
}
```

### 3. AggregationExecutor (ES 실행)

```kotlin
// aggregation/service/AggregationExecutor.kt
@Component
class AggregationExecutor(
    private val clientFactory: ElasticsearchClientFactory,
    private val dslBuilder: AggregationDslBuilder,
) {
    fun execute(clusterId: String, request: AggregationExecuteRequest): AggregationResult {
        val client = clientFactory.getClient(clusterId)
        val aggs = dslBuilder.build(request.aggregations)

        val response = client.search({ s ->
            s.index(request.index)
            s.size(0)  // 집계만, hits 불필요
            if (request.query != null) {
                s.query { q -> q.queryString { qs -> qs.query(request.query) } }
            }
            s.aggregations(aggs)
        }, Void::class.java)

        return AggregationResult(
            took = response.took(),
            totalHits = response.hits().total()?.value() ?: 0,
            aggregations = parseAggregations(response.aggregations()),
        )
    }
}
```

### 4. AggregationResponseParser

ES 9.x Aggregate는 variant 타입이므로 파싱이 필요합니다:

```kotlin
// aggregation/service/AggregationResponseParser.kt
fun parseAggregations(aggs: Map<String, Aggregate>): Map<String, Any> {
    return aggs.mapValues { (_, agg) -> parseAggregate(agg) }
}

private fun parseAggregate(agg: Aggregate): Any = when {
    agg.isSterms() -> agg.sterms().buckets().array().map { b ->
        mapOf(
            "key" to b.key().stringValue(),
            "doc_count" to b.docCount(),
            "sub" to parseAggregations(b.aggregations()),
        )
    }
    agg.isLterms() -> agg.lterms().buckets().array().map { b ->
        mapOf("key" to b.key(), "doc_count" to b.docCount())
    }
    agg.isDateHistogram() -> agg.dateHistogram().buckets().array().map { b ->
        mapOf(
            "key_as_string" to b.keyAsString(),
            "key" to b.key(),
            "doc_count" to b.docCount(),
        )
    }
    agg.isHistogram() -> agg.histogram().buckets().array().map { b ->
        mapOf("key" to b.key(), "doc_count" to b.docCount())
    }
    agg.isRange() -> agg.range().buckets().array().map { b ->
        mapOf(
            "key" to b.key(),
            "from" to b.from(),
            "to" to b.to(),
            "doc_count" to b.docCount(),
        )
    }
    agg.isFilters() -> agg.filters().buckets().keyed().map { (k, b) ->
        mapOf("key" to k, "doc_count" to b.docCount())
    }
    agg.isAvg() -> mapOf("value" to agg.avg().value())
    agg.isSum() -> mapOf("value" to agg.sum().value())
    agg.isMin() -> mapOf("value" to agg.min().value())
    agg.isMax() -> mapOf("value" to agg.max().value())
    agg.isCardinality() -> mapOf("value" to agg.cardinality().value())
    agg.isValueCount() -> mapOf("value" to agg.valueCount().value())
    else -> mapOf("raw" to agg.toString())
}
```

