### 6. 필드 자동완성 로직

인덱스 매핑에서 집계 가능한 필드를 추출합니다:

```kotlin
// aggregation/service/AggregationFieldService.kt
@Component
class AggregationFieldService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    // 필드 타입 → 사용 가능한 집계 유형 매핑
    private val FIELD_TYPE_TO_AGGREGATIONS = mapOf(
        "keyword" to listOf(TERMS, FILTERS, CARDINALITY, VALUE_COUNT),
        "text" to listOf(FILTERS),  // text는 terms 불가 (fielddata 필요)
        "long" to listOf(TERMS, HISTOGRAM, RANGE, AVG, SUM, MIN, MAX, CARDINALITY, VALUE_COUNT),
        "integer" to listOf(TERMS, HISTOGRAM, RANGE, AVG, SUM, MIN, MAX, CARDINALITY, VALUE_COUNT),
        "double" to listOf(HISTOGRAM, RANGE, AVG, SUM, MIN, MAX, CARDINALITY, VALUE_COUNT),
        "float" to listOf(HISTOGRAM, RANGE, AVG, SUM, MIN, MAX, CARDINALITY, VALUE_COUNT),
        "date" to listOf(DATE_HISTOGRAM, RANGE, MIN, MAX, CARDINALITY, VALUE_COUNT),
        "boolean" to listOf(TERMS, FILTERS, CARDINALITY, VALUE_COUNT),
        "ip" to listOf(TERMS, CARDINALITY, VALUE_COUNT),
    )

    fun getAggregableFields(clusterId: String, index: String): List<AggregableField> {
        val client = clientFactory.getClient(clusterId)
        val mappingResponse = client.indices().getMapping { it.index(index) }

        val properties = mappingResponse[index]
            ?.mappings()
            ?.properties() ?: return emptyList()

        return flattenProperties(properties, prefix = "")
    }

    private fun flattenProperties(
        props: Map<String, Property>,
        prefix: String,
    ): List<AggregableField> {
        return props.flatMap { (name, prop) ->
            val fullName = if (prefix.isEmpty()) name else "$prefix.$name"
            val typeName = prop._kind().name.lowercase()
            val supportedAggs = FIELD_TYPE_TO_AGGREGATIONS[typeName] ?: emptyList()

            val current = if (supportedAggs.isNotEmpty()) {
                listOf(AggregableField(fullName, typeName, supportedAggs))
            } else emptyList()

            // nested properties 재귀 탐색
            val nested = if (prop.isObject() && prop.`object`().properties() != null) {
                flattenProperties(prop.`object`().properties()!!, fullName)
            } else emptyList()

            current + nested
        }
    }
}

data class AggregableField(
    val field: String,
    val type: String,
    val supportedAggregations: List<AggregationType>,
)
```

### 7. API 엔드포인트 설계

```kotlin
// aggregation/controller/AggregationController.kt
@RestController
@RequestMapping("/aggregation")
class AggregationController(
    private val executor: AggregationExecutor,
    private val fieldService: AggregationFieldService,
    private val queryRepository: AggregationQueryRepository,
) {
    // 집계 실행
    @PostMapping("/execute")
    fun execute(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: AggregationExecuteRequest,
    ): AggregationResult = executor.execute(clusterId, request)

    // 필드 자동완성 (집계 가능 필드 + 타입)
    @GetMapping("/fields/{index}")
    fun getFields(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable index: String,
    ): List<AggregableField> = fieldService.getAggregableFields(clusterId, index)

    // 저장된 쿼리 CRUD
    @PostMapping("/queries")
    fun saveQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: AggregationQuery,
    ): AggregationQuery = queryRepository.save(request.copy(clusterId = clusterId))

    @GetMapping("/queries")
    fun listQueries(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<AggregationQuery> = queryRepository.findAllByClusterId(clusterId)

    @GetMapping("/queries/{id}")
    fun getQuery(@PathVariable id: String): AggregationQuery =
        queryRepository.findById(id).orElseThrow()

    @DeleteMapping("/queries/{id}")
    fun deleteQuery(@PathVariable id: String) = queryRepository.deleteById(id)
}
